export default function Footer() {
  return (
    <footer className="bg-gray-100 p-6 text-center text-sm">
      <p className="font-medium">CloudBox</p>
      <p className="text-gray-600">Simple, secure cloud storage</p>
      <div className="mt-2 space-x-4">
        <a href="#">Privacy</a>
        <a href="#">Terms</a>
        <a href="#">Contact</a>
      </div>
      <p className="mt-2 text-xs">© 2026 CloudBox</p>
    </footer>
  );
}
